 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The prominent divider color is the one occurring as solid full rows;
    # replace those rows and every occurrence of that color in divider columns.
    counts = {}
    for row in grid:
        if len(set(row)) == 1:
            counts[row[0]] = counts.get(row[0], 0) + 1
    color = max(counts, key=counts.get)
    for r, row in enumerate(grid):
        if all(v == color for v in row):
            out[r] = [2] * w
    # Full vertical color stripe (may intersect other row colors) is the column
    # with this same divider color in every row.
    for c in range(w):
        if all(grid[r][c] == color for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    return out

if __name__ == '__main__':
    import json
    print(json.dumps(transform(json.loads(input()))))
